from pathlib import Path
import json,hashlib,subprocess,sys
R=Path(__file__).resolve().parents[3];M=R/'migrations/shared-alg001-l08-p001'
subprocess.run([sys.executable,str(M/'generator-v1/derive-source-v1.py'),'--check'],cwd=R,check=True,stdout=subprocess.DEVNULL)
m=json.loads((M/'native-v1/source-model-v1.json').read_text());d=json.loads((M/'audit-v1/decode-v1.json').read_text())
assert d['pass'] and d['contextClosed'] and (d['sourceBytes'],d['sourceSha256'],d['sampleRate'],d['channels'],d['decodedSamples'])==(m['stream']['bytes'],m['stream']['sha256'],22050,1,m['stream']['sampleCount'])
assert d['pcmSha256']=='d4fb99dd1ca0eaaa78479eb146314db737fa3a5b9c31113a930409c198b0b98a'
assert (m['fps'],m['rootFrameCount'],m['rootEntryFrame'],m['frameDomain'],m['frameCount'])==(12,10,6,'sprite-142',130)
for f in m['frames']:
 a,b=f['layers'];assert (a['alpha256'],a['scaleX'],a['scaleY'])==(b['alpha256'],b['scaleX'],b['scaleY'])
assert m['title']=='Graphing Linear Equations: Introduction'
course,activity=m['title'].rsplit(': ',1)
data={k:m[k] for k in ['animationId','title','fps','rootFrameCount','rootEntryFrame','frameDomain','frameCount']}
data.update(sourceSha256=m['source']['sha256'],courseTitle=course+':',activityTitle=activity,sourceTextIds=[t['characterId'] for t in m['texts']],backgroundColor=m['stage']['backgroundColor'],frames=[[f['layers'][1]['alpha256'],f['layers'][1]['scaleX'],f['layers'][1]['scaleY']] for f in m['frames']])
data['clockPlan']={'version':1,'sourceSwfSha256':m['source']['sha256'],'frameDomain':m['frameDomain'],'firstFrame':1,'frameCount':m['frameCount'],'fps':12,'playbackMode':'loop','decoder':{k:d[k] for k in ['sourceSha256','sourceBytes','sampleRate','channels','decodedSamples','pcmSha256']},'segments':[{'firstFrame':1,'firstDecodedSample':m['stream']['firstSeekSamples'],'endDecodedSample':d['decodedSamples']}],'emptyNegativeBlocks':[],'alignmentStatus':'source-run-candidate-not-original-runtime-accepted'}
p=R/'packages/demos/src/generated/alg-l08-p001-source-v1.ts'
text='// Generated by migrations/shared-alg001-l08-p001/generator-v1/derive-product-v1.py.\nimport type {SourceTitleConfigV1} from "../source-title-state-v1";\nexport const ALG_L08_P001_SOURCE = '+json.dumps(data,ensure_ascii=False,separators=(',',':'))+' as const satisfies SourceTitleConfigV1;\n'
if '--check' in sys.argv:assert p.read_text()==text
else:p.open('x').write(text)
print(json.dumps({'pass':True,'frames':len(data['frames']),'output':str(p.relative_to(R)),'registered':False}))
